import { parseRange } from './parse-range';
// parse-range.js: export function parseRange(text) { return text.split('-'); }

export function bounds(text) {
  const parts = parseRange(text);
  const start = Number(parts[0]);
  const end = Number(parts[1]);
  if (!Number.isFinite(start) || !Number.isFinite(end)) {
    return null;
  }
  if (end < start) {
    return null;
  }
  return { start, end };
}
